exercise.referenceSolution:
#include <iostream>
#include <memory>
#include <vector>
#include <utility>
#include <string>

struct Probe { int kind = 0; Probe() = default; Probe(const Probe&): kind(1) {} Probe(Probe&&) noexcept: kind(2) {} };
int solve(int a, int b) { (void)a; (void)b; Probe x; const Probe y; Probe first(std::move(x)), second(std::move(y)); return 10 * first.kind + second.kind; }
